const PROJECT = '964775386a3ce03ecca883.03770715';
const BASE = 'https://api.lokalise.com/api2';
const url = BASE + '/projects/' + PROJECT + '/keys?include_screenshots=1&disable_references=1&filter_untranslated=1&limit=500&pagination=cursor';
return [{ json: { mode: 'keys', project: PROJECT, url: url } }];

const pages = $input.all();
const errors = [];
const rows = [];
for (const p of pages) {
  const r = p.json || {};
  const status = r.statusCode;
  const body = r.body !== undefined ? r.body : r;
  if (status !== undefined && status !== 200) { errors.push({ status: status, body: JSON.stringify(body).slice(0, 200) }); continue; }
  for (const k of (body.keys || [])) {
    if (k.is_archived) { continue; }
    const kn = k.key_name || {};
    const name = kn.web || kn.other || kn.ios || kn.android || '';
    const shots = (k.screenshots || []).map(function (s) { return s.title; });
    rows.push({ id: k.key_id, n: name, d: k.description || '', t: (k.tags || []).sort(), s: shots.length, st: shots.join(' | ') });
  }
}
const tagCount = {};
for (const r of rows) { for (const t of r.t) { tagCount[t] = (tagCount[t] || 0) + 1; } }
const sample = [];
const want = ['report::overview::title', 'report::safetyRecallCheck::title', 'pages::vin_lookup::hero::title', 'components::faqs_general::question_1::question', 'report::classic::toc::oemOptions', 'ui::sectionCard::ariaLabelFlag', 'report::vehicleSpecs::title', 'pages::vin_lookup::checkout::title'];
for (const w of want) { for (const r of rows) { if (r.n === w) { sample.push({ n: r.n, d: r.d, t: r.t.join(','), st: r.st }); break; } } }
for (const r of rows) { if (sample.length < 12 && r.s === 2 && r.n.indexOf('report::sales') === 0) { sample.push({ n: r.n, d: r.d, t: r.t.join(','), st: r.st }); } }
return [{ json: {
  count: rows.length,
  with_desc: rows.filter(function (x) { return x.d.trim(); }).length,
  no_desc: rows.filter(function (x) { return !x.d.trim(); }).length,
  with_shot: rows.filter(function (x) { return x.s > 0; }).length,
  two_shots: rows.filter(function (x) { return x.s === 2; }).length,
  over_cap: rows.filter(function (x) { return x.s > 2; }).map(function (x) { return x.n; }),
  no_tags: rows.filter(function (x) { return x.t.length === 0; }).length,
  screen_tags: Object.keys(tagCount).filter(function (t) { return t.indexOf('screen_') === 0; }).length,
  tagCount: tagCount,
  errors: errors,
  sample: sample
} }];
